--
-- Table structure for table `indikator_skor`
--

DROP TABLE IF EXISTS `indikator_skor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `indikator_skor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mitra_id` int(11) NOT NULL,
  `kode_indikator` varchar(5) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `bobot` tinyint(4) NOT NULL,
  `referensi_baseline` text DEFAULT NULL,
  `kondisi_baseline` text DEFAULT NULL,
  `kondisi_saat_ini` text DEFAULT NULL,
  `status_pemeriksaan` varchar(50) NOT NULL DEFAULT 'BELUM DITELAAH',
  `temuan_bukti` text DEFAULT NULL,
  `skor` tinyint(4) DEFAULT NULL,
  `alasan_skor` text DEFAULT NULL,
  `catatan_tindak_lanjut` text DEFAULT NULL,
  `nilai` decimal(6,2) DEFAULT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_mitra_indikator` (`mitra_id`,`kode_indikator`),
  KEY `updated_by` (`updated_by`),
  CONSTRAINT `indikator_skor_ibfk_1` FOREIGN KEY (`mitra_id`) REFERENCES `mitra_kinerja` (`id`) ON DELETE CASCADE,
  CONSTRAINT `indikator_skor_ibfk_2` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_skor_range` CHECK (`skor` is null or `skor` between 0 and 4)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `indikator_skor`
--

LOCK TABLES `indikator_skor` WRITE;
/*!40000 ALTER TABLE `indikator_skor` DISABLE KEYS */;
INSERT INTO `indikator_skor` (`id`, `mitra_id`, `kode_indikator`, `deskripsi`, `bobot`, `referensi_baseline`, `kondisi_baseline`, `kondisi_saat_ini`, `status_pemeriksaan`, `temuan_bukti`, `skor`, `alasan_skor`, `catatan_tindak_lanjut`, `nilai`, `updated_by`, `updated_at`) VALUES (1,1,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','Belum tersedia PIC formal maupun rencana aksi terpadu pada data terbaru. Namun pelaksanaan aktual pada edukasi KI dan stand pelayanan publik menunjukkan adanya koordinasi operasional. File eviden baru yang diunggah belum terisi substantif.','BUKTI MEMADAI','Final baseline; workbook P01 gabungan; file dekranasda.xlsx yang masih menunjukkan Total Kegiatan 0 dan placeholder PIC.',1,'Pengelolaan operasional mulai terlihat dari adanya kegiatan, tetapi penanggung jawab formal, pembagian peran, mekanisme koordinasi, dan rencana tindak lanjut belum jelas. Sesuai rubrik I1, skor 1.','Tetapkan PIC internal/mitra, susun rencana aksi per ruang lingkup, dan tetapkan mekanisme koordinasi berkala.',2.50,NULL,'2026-09-28 06:56:03'),(2,1,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Terdapat implementasi pada 2 dari 5 ruang lingkup: edukasi/pemahaman KI melalui Kelas Kreatif UMKM Dekrafest dan pelayanan pendaftaran KI melalui stand pelayanan publik pada beberapa periode. Tiga ruang lingkup lain masih belum diperoleh datanya.','BUKTI MEMADAI','RL10 Peningkatan Pemahaman KI; RL09 Pelayanan Pendaftaran KI; evidence berupa tautan publikasi dan laporan MIC 2025/2026.',2,'Sebagian tindak lanjut telah dilaksanakan, tetapi masih terdapat gap berarti pada tiga ruang lingkup lain. Sesuai rubrik I2, skor 2.','Aktivasi inventarisasi KIK, penegakan hukum KI, dan pertukaran data/informasi KI; catat target dan realisasinya.',7.50,NULL,'2026-09-28 06:56:03'),(3,1,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Output tersedia pada kegiatan edukasi KI dan stand pelayanan publik: penyampaian materi, layanan informasi/pelayanan KI, serta pelaksanaan stand pada beberapa tanggal. Output pada tiga ruang lingkup lainnya belum tersedia.','BUKTI MEMADAI','RL10 dan RL09 beserta tautan/laporan kegiatan; tiga ruang lingkup lain berstatus BELUM DIPEROLEH.',2,'Sebagian output tercapai dan dapat dijelaskan, tetapi cakupannya belum mewakili keseluruhan ruang lingkup. Rubrik I3 skor 2.','Tetapkan output minimal untuk seluruh ruang lingkup dan buat daftar output per periode.',7.50,NULL,'2026-09-28 06:56:04'),(4,1,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Final baseline belum memiliki data outcome/manfaat terukur.','Final baseline belum memiliki data outcome/manfaat terukur.','Manfaat awal terlihat: meningkatnya pemahaman UMKM mengenai legalitas dan perlindungan KI serta meningkatnya akses masyarakat terhadap informasi dan layanan KI. Manfaat masih bersifat kualitatif dan belum dilengkapi ukuran penerima/manfaat.','BUKTI MEMADAI','Outcome/manfaat pada RL10 dan RL09; belum ada metrik kuantitatif konsisten.',2,'Manfaat terlihat pada sebagian sasaran tetapi belum terukur secara konsisten. Sesuai rubrik I4, skor 2.','Ukur peserta/UMKM yang dilayani, konsultasi, permohonan KI, tindak lanjut pendaftaran, serta perubahan pemahaman.',10.00,NULL,'2026-09-28 06:56:04'),(5,1,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Kontribusi dapat dijelaskan pada peningkatan literasi hukum KI dan akses pelayanan KI bagi UMKM/masyarakat, tetapi belum ada pengukuran kontribusi pada sasaran kinerja secara terstruktur.','BUKTI MEMADAI','RL10 dan RL09 menyebut dukungan pada literasi hukum, akses pelayanan, dan kualitas pelayanan publik KI.',2,'Kontribusi dapat dijelaskan dan didukung sebagian evidence, tetapi belum terukur pada indikator kinerja. Rubrik I5 skor 2.','Hubungkan outcome dengan indikator layanan KI, pendaftaran KI, dan sasaran pemberdayaan UMKM.',10.00,NULL,'2026-09-28 06:56:04'),(6,1,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Evidence tersedia untuk dua ruang lingkup melalui tautan publikasi serta nama laporan MIC, tetapi masih terbatas dan tersebar. File eviden baru yang diunggah belum berisi data kegiatan atau bukti tambahan.','BUKTI MEMADAI','Tautan publikasi RL10; LAPORAN MIC 2025/2026 pada RL09; dekranasda.xlsx belum menambah evidence substantif.',1,'Evidence sangat terbatas dan belum cukup tertata untuk keseluruhan kerja sama. Sesuai rubrik I6, skor 1.','Bangun repository P01, indeks bukti per ruang lingkup, dan minta paket evidence lengkap dari mitra/PIC.',2.50,NULL,'2026-09-28 06:56:04'),(7,1,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Perjanjian masih berlaku sampai 14 November 2030. Risiko utama adalah implementasi yang belum merata, tidak adanya PIC/rencana aksi formal, serta tiga ruang lingkup tanpa data. Belum terlihat mekanisme mitigasi yang terstruktur.','BUKTI MEMADAI','Final baseline; ringkasan P01; tidak ada usulan tindak lanjut pada file eviden baru.',1,'Risiko dapat dikenali tetapi penanganannya masih lemah dan belum terstruktur. Sesuai rubrik I7, skor 1.','Tetapkan owner risiko, rencana aksi, target aktivasi tiga ruang lingkup, dan review triwulanan.',2.50,NULL,'2026-09-28 06:56:04'),(8,2,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','PIC internal diasumsikan telah ditetapkan melalui SK. PIC mitra utama dan cadangan sudah tersedia. Mitra juga menyampaikan 5 usulan tindak lanjut dengan target waktu. Mekanisme koordinasi pembaruan konten masih perlu diperjelas, termasuk siapa penanggung jawab di Kanwil.','BUKTI MEMADAI','SK PIC internal (diasumsikan tersedia untuk contoh); Data Stakeholder ù sheet IDENTITAS & PIC dan USULAN TINDAK LANJUT; 5 rencana tindak lanjut dan PIC mitra utama/cadangan.',2,'Penanggung jawab dan rencana tindak lanjut sudah mulai jelas, tetapi mekanisme koordinasi dan pembagian peran operasional untuk pembaruan konten belum sepenuhnya tegas. Sesuai rubrik, kondisi ini berada pada skor 2.','Tetapkan alur koordinasi pembaruan materi, PIC internal yang menjadi focal point, serta kalender tindak lanjut bersama BNNP Kepri.',5.00,NULL,'2026-09-28 06:56:04'),(9,2,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Implementasi sudah mulai berjalan. Data mitra mencatat integrasi materi Kanwil Hukum ke BESTI Learning Hub berstatus Sedang Berjalan. Data internal memverifikasi penyediaan/penayangan materi publikasi layanan hukum melalui BESTI, sementara ruang lingkup narasumber belum dilaksanakan.','BUKTI MEMADAI','Data Stakeholder ù PELAKSANAAN KEGIATAN; RL26 Kolaborasi Kampanye; RL28 Infografis/Videografis; BESTI Learning Hub: https://bestilearninghub.id/category/literasi-hukum/; RL27 menunjukkan ruang lingkup narasumber belum dilaksanakan.',2,'Sebagian tindak lanjut telah dilaksanakan dan dapat dibuktikan, tetapi implementasi belum mencakup seluruh ruang lingkup dan sebagian kegiatan masih berjalan. Sesuai rubrik I2: sebagian tindak lanjut terlaksana dengan gap yang masih berarti.','Selesaikan integrasi materi, lanjutkan e-book/modul, dan mulai realisasi ruang lingkup narasumber/podcast/webinar sesuai prioritas.',7.50,NULL,'2026-09-28 06:56:04'),(10,2,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Output awal sudah tersedia berupa konten/materi publikasi layanan hukum Kanwil Kemenkum Kepri pada BESTI Learning Hub. Namun output belum lengkap untuk seluruh ruang lingkup, khususnya e-book/modul dan kegiatan narasumber.','BUKTI MEMADAI','RL26 dan RL28 mencatat output tersedianya konten/materi publikasi layanan hukum pada BESTI; https://bestilearninghub.id/category/literasi-hukum/; RL24 dan RL27 menunjukkan sebagian output belum terbentuk.',2,'Output nyata sudah ada dan dapat ditelusuri, tetapi baru mencakup sebagian ruang lingkup. Rubrik I3 skor 2 sesuai dengan kondisi sebagian output tercapai.','Inventarisasi output per ruang lingkup dan tetapkan target minimum: konten, e-book/modul, kampanye, serta kegiatan narasumber.',7.50,NULL,'2026-09-28 06:56:04'),(11,2,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Final baseline belum memiliki data outcome/manfaat terukur.','Final baseline belum memiliki data outcome/manfaat terukur.','Manfaat awal sudah terindikasi secara kualitatif, antara lain bertambahnya variasi materi pembelajaran dan meluasnya kanal penyebaran informasi hukum melalui BESTI. Namun usia PKS baru sekitar 2,5 bulan, sehingga belum cukup periode observasi untuk menilai outcome secara objektif.','BELUM DAPAT DINILAI','Data Stakeholder ù PELAKSANAAN KEGIATAN kolom Hasil/Manfaat; RL26/RL28 kolom Outcome/Manfaat; tautan BESTI Learning Hub. Data ini dicatat sebagai indikasi manfaat awal, bukan dasar pemberian skor outcome.',NULL,'Outcome belum diberi skor bukan karena bukti tidak ada, melainkan karena jangka waktu implementasi sejak 13 Juli 2026 sampai periode penilaian 27 September 2026 belum memadai untuk menilai perubahan/manfaat secara matang.','Tetapkan indikator outcome dan mulai kumpulkan jumlah konten, akses/pengguna, tayangan, pemanfaatan materi, serta umpan balik. Nilai I4 pada review berikutnya setelah periode observasi memadai.',NULL,NULL,'2026-09-28 06:56:04'),(12,2,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Arah kontribusi awal dapat dijelaskan: BESTI mendukung diseminasi informasi hukum dan penyuluhan hukum melalui kanal digital. Namun pada usia PKS sekitar 2,5 bulan, hubungan antara output dengan capaian kinerja/pelayanan belum cukup matang untuk dinilai.','BELUM DAPAT DINILAI','RL26/RL28 mencatat arah kontribusi terhadap diseminasi informasi hukum dan penyuluhan hukum; BESTI Learning Hub menjadi kanal pelaksanaan. Data ini diperlakukan sebagai arah kontribusi awal, belum sebagai dampak yang dinilai.',NULL,'Kontribusi/dampak belum diberi skor karena periode implementasi masih terlalu awal. Penilaian baru dilakukan setelah outcome mulai terbentuk dan dapat dihubungkan dengan indikator kinerja atau pelayanan yang relevan.','Pada review berikutnya, hubungkan outcome terverifikasi dengan indikator publikasi/penyuluhan, pemanfaatan layanan, atau sasaran kinerja yang relevan.',NULL,NULL,'2026-09-28 06:56:04'),(13,2,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Evidence pasca-baseline sudah tersedia dari data mitra, matriks internal per ruang lingkup, P2MA, dan tautan BESTI. Namun evidence masih tersebar, belum seluruh ruang lingkup memiliki bukti, dan belum ada repository/index terpadu untuk scorecard.','BUKTI MEMADAI','Data Stakeholder; RL24, RL26, RL27, RL28; naskah/P2MA; https://bestilearninghub.id/category/literasi-hukum/; SK PIC internal diasumsikan tersedia.',2,'Evidence utama sudah tersedia dan dapat ditelusuri, tetapi kelengkapan dan keteraturan antar-ruang lingkup belum konsisten. Ini sesuai rubrik I6 skor 2.','Buat satu folder/repository evidence P02, indeks per ruang lingkup, dan log versi/tanggal bukti.',5.00,NULL,'2026-09-28 06:56:04'),(14,2,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku masih panjang sampai 12 Juli 2029. Risiko utama saat ini adalah kebutuhan penyesuaian materi dan kejelasan koordinasi dengan narasumber/pengelola. PIC mitra tersedia, PIC internal diasumsikan telah ditetapkan, dan terdapat rencana tindak lanjut untuk pengembangan konten serta evaluasi.','BUKTI MEMADAI','Final baseline masa berlaku; Data Stakeholder ù kendala/catatan, PIC, dan usulan tindak lanjut; RL26/RL28 mencatat tidak ada hambatan material dan rencana penambahan materi.',2,'Risiko utama sudah mulai dikenali dan terdapat tindak lanjut, tetapi mekanisme mitigasi, evaluasi berkala, dan pengukuran keberlanjutan belum kuat. Rubrik I7 skor 2.','Tetapkan mitigasi risiko sederhana: owner, jadwal update materi, mekanisme persetujuan konten, dan evaluasi pemanfaatan minimal tahunan.',5.00,NULL,'2026-09-28 06:56:04'),(15,3,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','PIC mitra utama dan cadangan sudah tersedia dan aktif dalam koordinasi. Terdapat 2 usulan tindak lanjut dengan target dan pihak yang dilibatkan, serta pelaksanaan aktual menunjukkan koordinasi lintas ruang lingkup. PIC internal individual belum tercantum secara eksplisit dalam paket data.','BUKTI MEMADAI','Data Stakeholder ù IDENTITAS & PIC; USULAN TINDAK LANJUT; 10 kegiatan aktual dengan bukti; matriks internal RL14ûRL18.',2,'Penanggung jawab mitra dan sebagian rencana tindak lanjut sudah jelas serta koordinasi operasional terbukti berjalan. Namun pengampu/PIC internal individual dan pembagian peran lintas seluruh ruang lingkup belum terdokumentasi secara konsisten. Sesuai rubrik I1, kondisi ini berada pada skor 2.','Tetapkan/tegaskan focal point internal per ruang lingkup, susun daftar PIC aktif, dan satukan rencana tindak lanjut dalam kalender kerja bersama.',5.00,NULL,'2026-09-28 06:56:04'),(16,3,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Implementasi telah berjalan nyata. Mitra melaporkan 10 kegiatan yang seluruhnya sudah dilaksanakan dan memiliki bukti, meliputi layanan/pembinaan Posbankum serta harmonisasi produk hukum daerah. Data internal juga menunjukkan pelaksanaan Posbankum, JDIH, dan harmonisasi. Layanan AHU belum dilaksanakan dan data KI belum diperoleh.','BUKTI MEMADAI','Data Stakeholder ù PELAKSANAAN KEGIATAN: 10 kegiatan, 10 bukti; RL14 Produk Hukum; RL15 Posbankum; RL16 JDIH; RL17 AHU; RL18 KI.',3,'Tindak lanjut utama telah terlaksana dan berjalan cukup konsisten pada beberapa ruang lingkup utama, dengan bukti kegiatan yang dapat ditelusuri. Belum mencapai skor 4 karena implementasi belum merata pada layanan AHU dan KI.','Pertahankan kesinambungan Posbankum, harmonisasi, dan JDIH; aktivasi tindak lanjut AHU; konfirmasi dan tindak lanjuti status layanan KI.',11.25,NULL,'2026-09-28 06:56:04'),(17,3,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Output nyata telah dihasilkan: layanan Posbankum, koordinasi/evaluasi dan pembinaan paralegal, hasil harmonisasi Ranperda/Ranperwako, serta output asistensi JDIH. Output belum merata pada seluruh ruang lingkup karena AHU belum berjalan dan KI belum terkonfirmasi.','BUKTI MEMADAI','10 kegiatan dan link bukti dari Pemkot Tanjungpinang; RL14 mencatat Surat Penyampaian Hasil/e-Harmonisasi; RL15 mencatat Posbankum; RL16 mencatat laporan/dokumentasi JDIH.',3,'Sebagian besar output utama pada ruang lingkup yang aktif telah tercapai dan dapat dibuktikan. Belum skor 4 karena output belum lengkap/konsisten pada seluruh ruang lingkup kerja sama.','Buat daftar output per ruang lingkup dan target tahunan agar capaian AHU, KI, JDIH, Posbankum, dan produk hukum dapat dibandingkan secara periodik.',11.25,NULL,'2026-09-28 06:56:05'),(18,3,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Final baseline belum memiliki data outcome/manfaat terukur.','Final baseline belum memiliki data outcome/manfaat terukur.','Manfaat sudah terlihat pada beberapa sasaran: masyarakat memperoleh layanan konsultasi/informasi hukum dan pendampingan melalui Posbankum; kesiapan pengelolaan JDIH meningkat; serta harmonisasi menghasilkan rancangan produk hukum yang lebih selaras. Namun ukuran kuantitatif outcome belum konsisten.','BUKTI MEMADAI','Data Stakeholder ù hasil/manfaat 10 kegiatan; RL14 outcome harmonisasi; RL15 outcome layanan masyarakat; RL16 outcome kesiapan JDIH.',2,'Outcome telah terlihat pada sebagian sasaran dan proses, tetapi belum disertai indikator kuantitatif yang cukup untuk menunjukkan outcome utama secara terukur. Sesuai rubrik I4, skor 2.','Mulai ukur jumlah penerima layanan Posbankum, jumlah/jenis produk hukum yang diharmonisasi, tindak lanjut JDIH, serta indikator manfaat layanan lainnya.',10.00,NULL,'2026-09-28 06:56:05'),(19,3,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Final baseline belum memiliki data kontribusi/dampak terhadap kinerja organisasi atau pelayanan hukum.','Final baseline belum memiliki data kontribusi/dampak terhadap kinerja organisasi atau pelayanan hukum.','Kontribusi terhadap pelayanan hukum dapat dijelaskan: memperluas akses konsultasi dan bantuan hukum, memperkuat kualitas produk hukum daerah, serta mendukung pengelolaan dan akses informasi hukum melalui JDIH. Hubungan dengan indikator kinerja organisasi belum diukur secara konsisten.','BUKTI MEMADAI','RL14 kontribusi pada kualitas/kepastian hukum; RL15 kontribusi pada layanan masyarakat; RL16 kontribusi pada kualitas pengelolaan dan akses informasi hukum; 10 kegiatan Pemkot dengan bukti.',2,'Kontribusi terhadap kinerja/pelayanan dapat dijelaskan dan didukung sebagian data, namun belum ada ukuran kontribusi yang terstruktur dan terukur untuk keseluruhan portofolio. Sesuai rubrik I5, skor 2.','Hubungkan output/outcome dengan indikator layanan hukum, misalnya jumlah layanan Posbankum, jumlah harmonisasi, kualitas/kepatuhan produk hukum, dan indikator JDIH.',10.00,NULL,'2026-09-28 06:56:05'),(20,3,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Arsip resmi: BELUM TERSEDIA; P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Evidence pasca-baseline jauh lebih kuat: 10 kegiatan dari mitra memiliki tautan bukti, ditambah bukti internal pada e-Harmonisasi, laporan Posbankum, laporan/dokumentasi JDIH, dan naskah/P2MA. Namun evidence belum terkonsolidasi dalam satu repository dan data KI masih belum diperoleh.','BUKTI MEMADAI','10 tautan Google Drive dari Data Stakeholder; e-Harmonisasi; laporan/dokumentasi Posbankum dan JDIH; P2MA; RL14ûRL18.',2,'Evidence utama tersedia dan dapat ditelusuri, tetapi belum konsisten dalam kelengkapan dan tata kelolanya untuk seluruh ruang lingkup. Khusus layanan KI, data/evidence masih belum diperoleh. Sesuai rubrik I6, skor 2.','Konsolidasikan satu repository evidence P03, beri indeks per ruang lingkup dan periode, serta lengkapi data/evidence layanan KI dan status AHU.',5.00,NULL,'2026-09-28 06:56:05'),(21,3,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Perjanjian masih berlaku sampai 5 Januari 2031. Risiko/gap yang terlihat adalah ketidakmerataan implementasi antar ruang lingkup, kebutuhan pembinaan Posbankum berkelanjutan, tindak lanjut penguatan JDIH, belum adanya kegiatan AHU, dan belum diperolehnya data KI. Terdapat usulan tindak lanjut untuk penguatan paralegal dan harmonisasi.','BUKTI MEMADAI','Final baseline masa berlaku; RL15 hambatan Posbankum; RL16 kebutuhan tindak lanjut JDIH; RL17 AHU tidak ada kegiatan; RL18 KI belum diperoleh; Data Stakeholder ù USULAN TINDAK LANJUT.',2,'Risiko utama sudah terlihat dan sebagian mulai ditangani melalui tindak lanjut, tetapi masih ada gap penting pada pemerataan implementasi, tata kelola evidence, AHU, KI, serta pengukuran hasil. Sesuai rubrik I7, skor 2.','Tetapkan owner dan target mitigasi per gap, termasuk aktivasi AHU/KI, pembinaan Posbankum, tindak lanjut JDIH, dan review triwulanan.',5.00,NULL,'2026-09-28 06:56:05'),(22,4,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Unit pengampu, PIC internal/mitra, dan rencana tindak lanjut belum lengkap pada final baseline.','Unit pengampu, PIC internal/mitra, dan rencana tindak lanjut belum lengkap pada final baseline.','PIC mitra utama dan cadangan sudah jelas dan hadir dalam forum penguatan. Terdapat 3 usulan tindak lanjut, termasuk sosialisasi HAKI dan fasilitasi pendaftaran KI. Indikasi PIC internal ada pada baseline, tetapi dasar formal belum tersedia.','BUKTI MEMADAI','baperida.xlsx ù IDENTITAS & PIC dan USULAN TINDAK LANJUT; final baseline P04.',2,'Penanggung jawab mitra dan sebagian rencana tindak lanjut sudah jelas, tetapi pembagian peran dan mekanisme koordinasi internal belum konsisten. Rubrik I1 skor 2.','Konfirmasi PIC internal secara formal, tetapkan owner per ruang lingkup, dan lengkapi target waktu usulan 2û3.',5.00,1,'2026-09-28 06:56:05'),(23,4,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Terdapat 2 kegiatan pasca-baseline: Rapat Koordinasi Kelitbangan Kabupaten Bintan 2026 dan penyediaan data HAKI terdaftar untuk kebutuhan IGA 2026. Keterkaitan keduanya dengan ruang lingkup PKS tersedia secara umum, namun implementasi inti KI masih sangat awal.','BUKTI MEMADAI','baperida.xlsx ù 2 kegiatan berstatus Sudah Dilaksanakan, masing-masing memiliki tautan bukti.',1,'Tindak lanjut sudah mulai terjadi tetapi masih sangat terbatas dibanding lima ruang lingkup utama. Rubrik I2 skor 1.','Prioritaskan sosialisasi KI, fasilitasi pendaftaran, dan pembentukan/penguatan Sentra KI.',3.75,1,'2026-09-28 06:56:05'),(24,4,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Output awal berupa koordinasi kelitbangan dan tersedianya data HAKI terdaftar. Output ini berguna sebagai fondasi, tetapi belum merupakan output utama yang lengkap dari ruang lingkup sosialisasi, kapasitas SDM, fasilitasi pendaftaran, dan Sentra KI.','BUKTI MEMADAI','baperida.xlsx ù hasil/manfaat 2 kegiatan dan tautan bukti.',1,'Output masih sangat terbatas dibanding keluaran utama yang diharapkan. Rubrik I3 skor 1.','Tetapkan output minimum untuk sosialisasi, pendaftaran KI, peningkatan kapasitas, dan Sentra KI.',3.75,1,'2026-09-28 06:56:05'),(25,4,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Final baseline belum memiliki data outcome/manfaat terukur.','Final baseline belum memiliki data outcome/manfaat terukur.','Manfaat awal disebutkan berupa peningkatan koordinasi/sinergi kelitbangan dan pemenuhan data untuk IGA. Namun usia PKS baru 89 hari, sehingga outcome KI belum cukup matang untuk dinilai.','BELUM DAPAT DINILAI','baperida.xlsx ù hasil/manfaat awal dicatat sebagai indikasi, bukan dasar pemberian skor outcome.',NULL,'Outcome belum diberi skor karena periode implementasi belum memadai (<6 bulan), bukan karena bukti tidak ada.','Mulai kumpulkan indikator outcome: jumlah peserta, usulan/pendaftaran KI, layanan Sentra KI, dan pemanfaatan hasil.',NULL,1,'2026-09-28 06:56:05'),(26,4,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Final baseline belum memiliki data kontribusi/dampak.','Final baseline belum memiliki data kontribusi/dampak.','Arah kontribusi pada inovasi daerah dan pemanfaatan data KI mulai terlihat, tetapi hubungan dengan capaian kinerja/pelayanan KI belum cukup matang pada usia PKS 89 hari.','BELUM DAPAT DINILAI','baperida.xlsx ù manfaat awal dan usulan tindak lanjut; belum ada outcome matang.',NULL,'Kontribusi/dampak belum dinilai karena masa implementasi masih awal.','Nilai kontribusi setelah outcome pendaftaran, kapasitas SDM, atau Sentra KI mulai terbentuk.',NULL,1,'2026-09-28 06:56:05'),(27,4,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Arsip dan P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Arsip dan P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Evidence pasca-baseline tersedia untuk 2 kegiatan melalui tautan Google Drive, dan data PIC/identitas mitra terisi. Namun data internal per 5 ruang lingkup masih berstatus BELUM DIPEROLEH dan evidence belum terstruktur.','BUKTI MEMADAI','baperida.xlsx; workbook P04 gabungan; final baseline P04.',2,'Evidence utama awal tersedia tetapi kelengkapan dan keteraturan antar ruang lingkup belum konsisten. Rubrik I6 skor 2.','Buat repository P04 dan indeks bukti per kegiatan/ruang lingkup; sinkronkan data internal dengan bukti mitra.',5.00,1,'2026-09-28 06:56:05'),(28,4,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Risiko utama pada masa awal adalah belum jelasnya PIC internal formal, tindak lanjut yang belum memiliki target lengkap, dan implementasi inti KI yang masih terbatas. Terdapat 3 usulan tindak lanjut sebagai dasar keberlanjutan.','BUKTI MEMADAI','baperida.xlsx ù PIC, 3 usulan tindak lanjut, 2 kegiatan; final baseline.',2,'Risiko utama mulai dikenali dan terdapat arah tindak lanjut, tetapi mitigasi dan pengendalian belum matang. Rubrik I7 skor 2.','Tetapkan target waktu, owner, dan review bulanan selama masa implementasi awal.',5.00,1,'2026-09-28 06:56:05'),(29,5,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama telah memiliki penanggung jawab yang jelas, rencana tindak lanjut yang dapat dilaksanakan, dan mekanisme koordinasi untuk memastikan tindak lanjut tersebut berjalan?',10,'Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','Unit pengampu, PIC internal, PIC mitra, dan rencana tindak lanjut: BELUM TERSEDIA pada final baseline.','PIC mitra utama dan cadangan sudah jelas dan PIC utama hadir dalam forum penguatan. Pelaksanaan kegiatan menunjukkan koordinasi, tetapi PIC internal dan rencana aksi terpadu belum tersedia; file mitra tidak memuat usulan tindak lanjut.','BUKTI MEMADAI','stain sar.xlsx ù IDENTITAS & PIC; RINGKASAN usulan 0; workbook P05 gabungan.',1,'Penanggung jawab mitra sudah diketahui, tetapi pembagian peran internal dan rencana tindak lanjut belum jelas. Rubrik I1 skor 1.','Tetapkan PIC internal dan susun rencana aksi seluruh ruang lingkup dengan target waktu.',2.50,NULL,'2026-09-28 06:56:06'),(30,5,'I2','Implementasi / Tindak Lanjut\nCara periksa: Apakah kerja sama telah ditindaklanjuti melalui kegiatan atau langkah implementasi yang relevan dan dapat dibuktikan?',15,'Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan hasil: BELUM TERSEDIA pada final baseline.','Implementasi terbukti pada pendidikan/pengajaran melalui narasumber KI, fasilitasi pencatatan 4 ciptaan, dan satu fasilitasi pendaftaran KI yang sedang berjalan dengan nomor pendaftaran EC002026157468. Sebagian besar ruang lingkup lain belum menunjukkan pelaksanaan.','BUKTI MEMADAI','RL01 Pendidikan; RL05 KI; stain sar.xlsx ù PELAKSANAAN KEGIATAN.',2,'Sebagian tindak lanjut telah dilaksanakan, tetapi gap antar ruang lingkup masih berarti. Rubrik I2 skor 2.','Aktifkan penelitian, pengabdian, MBKM, kompetensi SDM, dan JDIH melalui kalender kegiatan bersama.',7.50,NULL,'2026-09-28 06:56:06'),(31,5,'I3','Output\nCara periksa: Apakah kegiatan menghasilkan produk/hasil langsung yang seharusnya dicapai?',15,'Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Pelaksanaan dan eviden implementasi: BELUM TERSEDIA pada final baseline.','Output tersedia berupa penyampaian materi KI, terbitnya sertifikat pencatatan atas 4 ciptaan, dan proses pendaftaran baru dengan nomor EC002026157468. Output belum merata pada ruang lingkup Tri Dharma dan layanan hukum lainnya.','BUKTI MEMADAI','Laporan Kegiatan 18 Desember 2025; data fasilitasi pencatatan cipta; stain sar.xlsx nomor pendaftaran EC002026157468.',2,'Sebagian output tercapai dan dapat dibuktikan, namun belum mewakili seluruh output utama kerja sama. Rubrik I3 skor 2.','Susun target output per ruang lingkup dan dokumentasikan capaian secara periodik.',7.50,NULL,'2026-09-28 06:56:06'),(32,5,'I4','Outcome\nCara periksa: Apakah output mulai memberi perubahan/manfaat kepada sasaran, proses, layanan, atau organisasi?',20,'Final baseline belum memiliki data outcome/manfaat terukur.','Final baseline belum memiliki data outcome/manfaat terukur.','Manfaat awal terlihat berupa meningkatnya pemahaman peserta tentang pelindungan KI serta tersedianya bukti administratif pencatatan karya dosen/mahasiswa. Manfaat belum diukur secara kuantitatif dan cakupannya masih terbatas.','BUKTI MEMADAI','Outcome pada RL01 dan RL05; stain sar.xlsx ù hasil \'Terdaftarnya karya dosen/mahasiswa\'.',2,'Manfaat terlihat pada sebagian sasaran tetapi belum terukur dan belum meluas ke sebagian besar ruang lingkup. Rubrik I4 skor 2.','Ukur jumlah dosen/mahasiswa terlayani, permohonan/sertifikat KI, pemanfaatan materi, dan tindak lanjut kegiatan Tri Dharma.',10.00,NULL,'2026-09-28 06:56:06'),(33,5,'I5','Kontribusi / Dampak\nCara periksa: Apakah hasil kerja sama berkontribusi terhadap sasaran kinerja organisasi dan/atau pelayanan hukum?',20,'Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Final baseline belum memiliki data kontribusi/dampak terhadap kinerja atau pelayanan.','Kontribusi dapat dijelaskan pada edukasi KI, fasilitasi pelindungan karya akademik, dan penguatan ekosistem KI di perguruan tinggi. Namun kontribusi terhadap sasaran kinerja keseluruhan kerja sama belum diukur.','BUKTI MEMADAI','RL01 dan RL05 mencatat kontribusi pada edukasi/diseminasi KI dan layanan fasilitasi/pelindungan KI.',2,'Kontribusi dapat dijelaskan dan didukung sebagian data, tetapi belum terukur dan belum mencakup seluruh portofolio. Rubrik I5 skor 2.','Hubungkan outcome KI dan Tri Dharma dengan indikator pelayanan hukum dan kinerja perguruan tinggi.',10.00,NULL,'2026-09-28 06:56:06'),(34,5,'I6','Evidence & Data\nCara periksa: Apakah data/evidence cukup, mutakhir, dan dapat ditelusuri ke sumbernya?',10,'Arsip dan P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Arsip dan P2MA: TERVERIFIKASI; eviden implementasi: BELUM TERSEDIA.','Evidence sudah tersedia berupa laporan kegiatan, data/sertifikat pencatatan 4 ciptaan, dan nomor pendaftaran KI baru. Namun banyak matriks ruang lingkup masih nihil/belum diperoleh dan terdapat beberapa versi data yang perlu direkonsiliasi.','BUKTI MEMADAI','P05 workbook gabungan; stain sar.xlsx; laporan kegiatan dan bukti pendaftaran KI.',2,'Evidence utama tersedia tetapi belum konsisten dalam kelengkapan dan keteraturan antar ruang lingkup. Rubrik I6 skor 2.','Rekonsiliasi versi data, konsolidasikan repository P05, dan indekskan bukti per ruang lingkup.',5.00,NULL,'2026-09-28 06:56:06'),(35,5,'I7','Risiko & Keberlanjutan\nCara periksa: Apakah risiko utama ditangani dan ada kondisi yang mendukung keberlanjutan manfaat?',10,'Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Masa berlaku: TERVERIFIKASI; hambatan/gap operasional: BELUM TERSEDIA.','Perjanjian masih berlaku sampai 18 Maret 2030. Risiko utama adalah implementasi yang terkonsentrasi pada KI/pendidikan, ketiadaan rencana aksi, PIC internal yang belum jelas, dan sebagian besar ruang lingkup belum aktif.','BUKTI MEMADAI','Final baseline; P05 gabungan; stain sar.xlsx menunjukkan usulan tindak lanjut 0.',1,'Risiko sudah dapat dikenali tetapi penanganannya belum terstruktur dan dukungan keberlanjutan lintas ruang lingkup masih lemah. Rubrik I7 skor 1.','Tetapkan rencana aksi tahunan, owner per ruang lingkup, dan review triwulanan untuk memastikan aktivasi kegiatan.',2.50,NULL,'2026-09-28 06:56:06'),(36,6,'I1','Kejelasan Pengelolaan & Rencana Tindak Lanjut\nCara periksa: Apakah pelaksanaan kerja sama tela