INSERT INTO `mitra_kinerja` (`id`, `kode`, `portofolio`, `nama_mitra`, `judul`, `jenis`, `bidang`, `pks_induk_id`, `tanggal_mulai`, `tanggal_berakhir`, `status_tanggal`, `evaluasi_per_tahun`, `baseline_status`, `baseline_locked_at`, `baseline_locked_by`, `baseline_pemeriksa`, `baseline_catatan_ringkasan`, `cutoff_date`, `sumber_baseline`, `pic_internal`, `pic_mitra`, `file_naskah`, `foto_kerjasama`, `pemeriksa_id`, `tanggal_review`, `status_scorecard`, `posisi_portofolio`, `rekomendasi`, `created_at`, `updated_at`) VALUES (1,'P01','Pilot Utama','Dewan Kerajinan Nasional Daerah Provinsi Kepulauan Riau','Peningkatan Perlindungan Kekayaan Intelektual Kriya, Wastra dan Fashion di Provinsi Kepulauan Riau','PKS','AHU',NULL,'2025-11-15','2030-11-14','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-09-28 14:03:01',1,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1787732310.pdf','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-09-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1787732310.pdf',NULL,1,'2026-09-22','SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI TERBATAS','LANJUTKAN DENGAN AKTIVASI RUANG LINGKUP DAN PENGUATAN TATA KELOLA\n\nTemuan Utama:\nDibanding baseline, terdapat implementasi nyata pada edukasi KI dan pelayanan pendaftaran KI, beserta manfaat awal bagi UMKM/masyarakat. Namun tiga ruang lingkup belum memiliki data, PIC/rencana aksi belum jelas, dan evidence masih terbatas.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal dan mitra; 2) susun rencana aksi 5 ruang lingkup; 3) aktifkan KIK, penegakan KI, dan pertukaran data; 4) konsolidasikan evidence; 5) ukur penerima layanan/UMKM dan tindak lanjut pendaftaran KI; 6) review triwulanan.','2026-09-22 03:33:35','2026-09-28 07:03:01'),(2,'P02','Pilot Utama','Badan Narkotika Nasional Provinsi Kepulauan Riau','Integrasi dan Pemanfaatan Belajar Seru Tiap Hari Learning Hub sebagai Platform Pembelajaran Digital dalam Penguatan Literasi Hukum, Pencegahan Penyalahgunaan Narkotika, dan Pembangunan Karakter Generasi Muda di Provinsi Kepulauan Riau','PKS','AHU',NULL,'2026-07-13','2029-07-13','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1785760147.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','OUTPUT AWAL / IMPLEMENTASI BERJALAN','LANJUTKAN IMPLEMENTASI DAN SIAPKAN PENGUKURAN HASIL\n\nTemuan Utama:\nSejak baseline, telah tersedia PIC mitra, rencana tindak lanjut, integrasi materi yang sedang berjalan, dan output awal berupa konten layanan hukum pada BESTI Learning Hub. Karena PKS baru berlaku sejak 13 Juli 2026, outcome dan kontribusi/dampak belum memasuki periode penilaian yang memadai.\n\nRencana Tindak Lanjut:\n1) Tegaskan focal point dan mekanisme update konten; 2) konsolidasikan repository evidence P02; 3) lanjutkan integrasi e-book/modul; 4) realisasikan kolaborasi narasumber/podcast/webinar; 5) mulai ukur konten, akses/pengguna, pemanfaatan dan umpan balik; 6) lakukan review outcome/kontribusi setelah periode implementasi memadai.','2026-09-22 03:33:35','2026-09-28 06:59:28'),(3,'P03','Pilot Utama','Pemerintah Kota Tanjungpinang','Pelayanan Hukum','MoU','AHU',NULL,'2026-01-06','2031-01-05','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Ischika','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778046924.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI AKTIF','LANJUTKAN DENGAN PENGUATAN IMPLEMENTASI, EVIDENCE, DAN PENGUKURAN OUTCOME\n\nTemuan Utama:\nDibanding baseline, kerja sama telah berkembang menjadi implementasi aktif: 10 kegiatan mitra seluruhnya memiliki bukti; Posbankum, harmonisasi produk hukum, dan JDIH menunjukkan output serta manfaat awal. Gap utama adalah pemerataan implementasi pada AHU/KI, penegasan PIC internal, konsolidasi evidence, dan pengukuran outcome/kontribusi.\n\nRencana Tindak Lanjut:\n1) Tegaskan PIC/focal point internal per ruang lingkup; 2) konsolidasikan repository evidence P03; 3) lanjutkan pembinaan Posbankum, harmonisasi, dan JDIH; 4) aktivasi tindak lanjut AHU dan klarifikasi layanan KI; 5) ukur penerima layanan, jumlah harmonisasi, capaian JDIH, serta outcome layanan; 6) lakukan review triwulanan.','2026-09-22 03:33:35','2026-09-28 06:59:29'),(4,'P04','Pilot Utama','Badan Perencanaan Pembangunan, Riset, dan Inovasi Daerah Kabupaten Bintan','Pelindungan dan Pemanfaatan Kekayaan Intelektual','PKS','AHU',NULL,'2026-06-30','2029-06-29','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Diana Martin (Badan Perencanaan Pembangunan Riset dan Inovasi Daerah Kabupaten Bintan)','https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1785760267.pdf',NULL,1,'2026-09-23','MASA IMPLEMENTASI AWAL','OUTPUT AWAL / IMPLEMENTASI BERJALAN','LANJUTKAN IMPLEMENTASI AWAL DAN BANGUN BUKTI HASIL\n\nTemuan Utama:\nDibanding baseline, kini telah tersedia PIC mitra, 3 usulan tindak lanjut, 2 kegiatan dengan bukti, dan output awal. Namun kerja sama masih dalam masa implementasi awal dan implementasi inti KI belum merata.\n\nRencana Tindak Lanjut:\n1) Konfirmasi PIC internal; 2) lengkapi target 3 usulan tindak lanjut; 3) laksanakan sosialisasi KI dan fasilitasi pendaftaran; 4) siapkan arah pembentukan/penguatan Sentra KI; 5) konsolidasikan evidence; 6) kumpulkan indikator outcome untuk review berikutnya.','2026-09-22 03:33:35','2026-09-28 06:59:30'),(5,'C01','Cadangan','Sekolah Tinggi Agama Islam Negeri Sultan Abdurrahman Kepulauan Riau','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nur\'ah Darina','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Dr. Fadhila Yonata, M.Pd (STAIN Sultan Abdurrahman Kepri)','https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758075052.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','OUTCOME AWAL / IMPLEMENTASI TERBATAS','LANJUTKAN DENGAN PERLUASAN IMPLEMENTASI DAN PENGUATAN TATA KELOLA\n\nTemuan Utama:\nDibanding baseline, sudah terdapat implementasi pada edukasi KI dan fasilitasi pendaftaran KI, termasuk 4 ciptaan tercatat dan satu pendaftaran baru yang sedang berjalan. Namun implementasi belum merata, tidak ada rencana tindak lanjut dari mitra, dan PIC internal/evidence lintas ruang lingkup masih perlu diperkuat.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) susun rencana aksi tahunan; 3) aktivasi penelitian, pengabdian, MBKM, kompetensi SDM dan JDIH; 4) lanjutkan fasilitasi KI dan pantau pendaftaran EC002026157468; 5) konsolidasikan evidence; 6) ukur outcome dan review triwulanan.','2026-09-22 03:33:35','2026-09-28 06:59:31'),(6,'P06','Pilot Utama','Universitas Maritim Raja Ali Haji (UMRAH)','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758074583.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','IMPLEMENTASI SANGAT TERBATAS / TATA KELOLA BELUM KUAT','SEGERA BENTUK TATA KELOLA OPERASIONAL DAN AKTIFKAN IMPLEMENTASI\n\nTemuan Utama:\nDibanding baseline, belum terdapat tambahan evidence substantif. Jejak implementasi yang dapat ditelusuri masih terbatas pada sertifikat peserta magang, sementara PIC, RTL, outcome, dan kontribusi belum terbukti.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC; 2) verifikasi kegiatan magang/kegiatan lain; 3) susun rencana aksi tahunan; 4) aktifkan ruang lingkup prioritas; 5) konsolidasikan evidence; 6) ukur outcome; 7) review triwulanan.','2026-09-22 03:33:35','2026-09-28 06:59:32'),(7,'P07','Pilot Utama','Sekolah Tinggi Agama Islam Paduka Anambas','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nadia Putri Boga','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1779175642.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','BELUM TERIMPLEMENTASI / TATA KELOLA OPERASIONAL BELUM TERBENTUK','AKTIFKAN KERJA SAMA SEGERA DAN BENTUK TATA KELOLA OPERASIONAL\n\nTemuan Utama:\nBelum ada perkembangan substantif dari baseline: belum terdapat PIC operasional, RTL, kegiatan, output, outcome, maupun evidence implementasi.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal/mitra; 2) pilih 1û2 ruang lingkup prioritas; 3) susun RTL dengan target 30û60 hari; 4) laksanakan kegiatan pertama; 5) bangun repository evidence; 6) review bulanan.','2026-09-22 03:33:35','2026-09-28 06:59:33'),(8,'P08','Pilot Utama','Politeknik Negeri Batam','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778058363.pdf',NULL,NULL,NULL,'SIAP DIVALIDASI','IMPLEMENTASI TERBATAS / RENCANA TINDAK LANJUT KUAT','PERCEPAT IMPLEMENTASI DAN TUNTASKAN TINDAK LANJUT PRIORITAS KI\n\nTemuan Utama:\nDibanding baseline, kini telah tersedia PIC mitra, satu kegiatan dengan bukti, dan empat usulan tindak lanjut yang sangat spesifik pada isu KI. Namun implementasi aktual masih terbatas dibanding luasnya ruang lingkup MoU.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) jadwalkan empat tindak lanjut KI; 3) pendampingan dokumen/pemeriksaan awal KI; 4) koordinasi isu tarif/prosedur dengan DJKI; 5) fasilitasi lisensi dan percepatan pemeriksaan paten; 6) mulai aktivasi ruang lingkup Tri Dharma lainnya; 7) ukur hasil dan konsolidasikan evidence.','2026-09-22 03:33:35','2026-09-28 06:59:34'),(9,'P09','Pilot Utama','Sekolah Tinggi Agama Islam Natuna','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-05-08','2031-05-07','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nur\'ah Darina','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Dedi Supriadi, SE (STAI Natuna)','https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1779268941.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','RENCANA IMPLEMENTASI TERSTRUKTUR / BELUM MULAI','MULAI IMPLEMENTASI SESUAI ROADMAP DAN BANGUN EVIDENCE SEJAK AWAL\n\nTemuan Utama:\nDibanding baseline, PIC mitra dan tujuh rencana tindak lanjut sudah tersedia dengan cukup rinci. Namun belum ada kegiatan aktual atau output, sehingga scorecard masih berada pada Masa Implementasi Awal.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal; 2) mulai pembentukan/penguatan Sentra KI; 3) laksanakan sosialisasi KI; 4) inventarisasi potensi KI; 5) buka klinik pendaftaran KI; 6) mulai program Hak Cipta/Merek prioritas; 7) siapkan SOP integrasi KI dengan penelitian/PkM; 8) dokumentasikan evidence dan review bulanan.','2026-09-22 03:33:35','2026-09-28 06:59:35'),(10,'P10','Pilot Utama','Sekolah Tinggi Ilmu Sosial dan Ilmu Politik Bunda Tanah Melayu','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-05-08','2031-05-07','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778249973.pdf',NULL,NULL,NULL,'MASA IMPLEMENTASI AWAL','MASA IMPLEMENTASI AWAL / TATA KELOLA BELUM TERBENTUK','BENTUK TATA KELOLA DAN MULAI IMPLEMENTASI AWAL\n\nTemuan Utama:\nBelum ada perkembangan substantif dari baseline. Tata kelola operasional dan evidence implementasi belum terbentuk, tetapi usia kerja sama masih di bawah 6 bulan.\n\nRencana Tindak Lanjut:\n1) Tetapkan PIC internal/mitra; 2) susun RTL 3û6 bulan; 3) pilih kegiatan prioritas; 4) laksanakan kegiatan pertama; 5) siapkan repository evidence; 6) review setelah melewati 6 bulan.','2026-09-22 03:33:35','2026-09-28 06:59:35'),(11,'C02','Cadangan','Politeknik Bintan Cakrawala','Fasilitasi Tri Dharma Perguruan Tinggi dan Pelayanan Hukum','MoU','AHU',NULL,'2025-03-19','2030-03-18','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Indah Andesta, S.Par., M.Sc (Politeknik Bintan Cakrawala)','https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1758074830.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','PERBAIKI','2026-09-22 03:33:35','2026-09-28 06:51:28'),(12,'P05','Pilot Utama','Sekolah Tinggi Ilmu Tarbiyah (STIT) Mumtaz Karimun','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2026-04-20','2031-04-19','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,NULL,'https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778059603.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','PERBAIKI','2026-09-22 03:33:35','2026-09-28 06:51:28'),(13,'C03','Cadangan','Universitas Ibnu Sina','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-11-18','2030-11-17','TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Nadia Putri Boga','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Amirullah (Bidang Kerja Sama)','https://p2ma.kemenkum.go.id/uploads/kerjasama/naskah/1778056915.pdf',NULL,NULL,NULL,'BELUM LENGKAP','BELUM DAPAT DITENTUKAN','PERBAIKI','2026-09-22 03:33:35','2026-09-28 06:51:28'),(14,'C04','Cadangan','Universitas Riau Kepulauan','Pelayanan Hukum dan Fasilitasi Tri Dharma Perguruan Tinggi','MoU','AHU',NULL,'2025-12-05','2030-12-04','BELUM TERVERIFIKASI',4,'TERVERIFIKASI / DIKUNCI','2026-08-28 23:59:59',1,'Kompilasi Pokja Data','Final Baseline dikunci per 28 Agustus 2026 berdasarkan hasil audit Pokja Data tanpa kontradiksi internal.','2026-08-28','Simulasi_Baseline_MITRA_KINERJA_Cutoff_28_Agustus_2026.xlsx',NULL,'Ajeng Handayani Purwaningrum, B.Ec., M.B.A (Kerjasama)','https://p2ma.kemenkum.go.id/uploads/kerjasama/n